import math

def find_sequence(n):
    # Generate the sequence a_i = i
    sequence = list(range(1, n + 1))
    return sequence

def main():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        sequence = find_sequence(n)
        print(' '.join(map(str, sequence)))

if __name__ == "__main__":
    main()
